  ('89b58421-a75d-5853-bf30-79ae3326bc41', null, (select id from public.skills where slug = 'read-g7-literary-structure-pov'), null, 'hard',
   $q$Why does the drama form, with its stage directions, work especially well for this scene?$q$, $q$[{"text":"The directions reveal what happens to the project's score after the fair ends.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"The directions let the characters tell the audience their private thoughts aloud.","is_correct":false,"misconception_token":"confuses-drama-terms"},{"text":"The directions show the audience a leak the characters ignore, which creates the humor.","is_correct":true},{"text":"The directions explain the science of volcanoes more clearly than the dialogue does.","is_correct":false,"misconception_token":"too-narrow"}]$q$::jsonb, $q$The directions show the audience a leak the characters ignore, which creates the humor.$q$, $q$Only the stage directions reveal the spreading puddle, so the audience watches the students' confident lines while knowing the truth. Characters do not share private thoughts in these directions; that would be an aside, which this scene does not use.$q$, 'draft', '09c2cecc-2d16-5b5d-a6f0-982e0ae381ca')
