-- Passage rg7-theme-summary-p01
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('95798cb6-09af-5539-8d52-3f98e2932f2c', 'rg7-theme-summary-p01', (select id from public.skills where slug = 'read-g7-theme-summary'), null,
        '6-8', $q$The Seed Library$q$, $q$Priya noticed the empty shelf the first week the Maplewood branch library reopened. A small sign above it read "Seed Library: Take Some, Leave Some." Nobody had left anything.

Her grandmother grew tomatoes on their apartment balcony, and every fall she dried the seeds on paper towels. Priya asked if she could bring a few packets to the library. Her grandmother laughed. "Twenty seeds will not fill a shelf," she said. Still, she helped Priya fold small envelopes and label them in neat letters.

For two weeks, the envelopes sat alone. Then a packet of marigold seeds appeared beside them, with a note that said "From the Okafor family." A week later, someone added beans. Mr. Delgado from the corner bakery brought pepper seeds his father had saved for thirty years.

By spring, the shelf was crowded. The librarian started a sign-up sheet for people who wanted to trade growing tips. Neighbors who had lived on the same street for years without speaking now stood together reading seed labels and comparing notes about sunlight.

In July, Priya walked past a fenced lot that had been empty for as long as she could remember. Bright tomato plants were climbing wooden stakes along the fence. A boy she did not know was watering them with a plastic jug. When she asked where the plants came from, he pointed toward the library. "Somebody's grandmother," he said.

Priya smiled and did not explain.$q$, 'draft')
