  ('8915fce3-3403-5008-bf9f-a3c1262f1277', null, (select id from public.skills where slug = 'read-g7-theme-summary'), null, 'easy',
   $q$Which statement best expresses a theme of the poem?$q$, $q$[{"text":"Aunts are wiser than anyone else in a family.","is_correct":false,"misconception_token":"overgeneralization"},{"text":"Tide pools are dangerous places for young children to play.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"Collecting shells is always a waste of time at the beach.","is_correct":false,"misconception_token":"overgeneralization"},{"text":"Patience and stillness let a person notice what hurry misses.","is_correct":true}]$q$::jsonb, $q$Patience and stillness let a person notice what hurry misses.$q$, $q$The speaker finds only broken shells while rushing, but sees a crab, starfish, snail and fish after sitting still. The poem never says shells are always a waste, only that hurrying made the speaker miss the pool.$q$, 'draft', '29de25e5-8e0c-5c59-bb0a-315239eaa221')
