  ('be74feea-e015-5d6b-b377-f8d29a6b9edd', null, (select id from public.skills where slug = 'read-g7-theme-summary'), null, 'medium',
   $q$How does the first stanza contribute to the theme?$q$, $q$[{"text":"It explains why the aunt chose to sit beside the gray rock.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"It shows that the speaker has already learned to be patient.","is_correct":false,"misconception_token":"wrong-sequence"},{"text":"It shows the speaker hurrying and finding only broken shells, setting up a contrast.","is_correct":true},{"text":"It describes the beach so the reader knows where the poem takes place.","is_correct":false,"misconception_token":"setting-not-theme"}]$q$::jsonb, $q$It shows the speaker hurrying and finding only broken shells, setting up a contrast.$q$, $q$The rushing speaker sees "only sand and water," which contrasts with the living pool found later through stillness. The stanza does give a setting, but its job in the theme is to show what hurrying misses.$q$, 'draft', '29de25e5-8e0c-5c59-bb0a-315239eaa221')
