  ('bf120f9d-49c3-5786-ae35-77b574d916d0', null, (select id from public.skills where slug = 'read-g7-theme-summary'), null, 'easy',
   $q$Which statement best expresses the theme of the passage?$q$, $q$[{"text":"Older brothers know more about science than their sisters.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"Winning first place is the only real reward at a fair.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"Music has no effect on any kind of living thing.","is_correct":false,"misconception_token":"overgeneralization"},{"text":"Honest results matter more than results that prove you right.","is_correct":true}]$q$::jsonb, $q$Honest results matter more than results that prove you right.$q$, $q$Soo-ah reports results that disprove her idea, and the judge praises her for showing "what actually happened." One small test of bean plants cannot show that music affects no living thing.$q$, 'draft', '6a36ddd6-d4a4-5460-81b9-8556965530dd')
