  ('4a5dd7e8-e897-5b0b-9efb-d878c5ed64e5', null, (select id from public.skills where slug = 'read-g8-authors-purpose'), null, 'hard',
   $q$Which sentence best shows the author combining his or her view with the opponents' concerns?$q$, $q$[{"text":"\"Fallen leaves are not trash.\"","is_correct":false,"misconception_token":"one-sided-evidence"},{"text":"\"Trucks must haul them away, and in some towns the bags end up in landfills.\"","is_correct":false,"misconception_token":"one-sided-evidence"},{"text":"\"With a little planning, a yard can look neat and still help the creatures that live there.\"","is_correct":true},{"text":"\"Every fall, many homeowners rake their lawns until not a single leaf remains.\"","is_correct":false,"misconception_token":"background-not-claim"}]$q$::jsonb, $q$"With a little planning, a yard can look neat and still help the creatures that live there."$q$, $q$This sentence joins the opponents' wish for a neat yard with the author's goal of helping wildlife. "Fallen leaves are not trash" states only the author's side.$q$, 'draft', 'b2b90ff1-915e-5d1d-9a20-f036f60d28c7')
